dtsPropsFor.Landschap:
/** Dieptelagen, bv. BOS_LAGEN of POLDER_LAGEN (exports van dit pakket), of maakBosLagen(DAGERAAD_PALET). */
  lagen: { id: string; diepte: number; kleur: string; svg: React.ReactNode }[];
  /** Muispositie, bv. van useMuisParallax() uit dit pakket. */
  muisX: import('motion/react').MotionValue<number>;
  muisY: import('motion/react').MotionValue<number>;
  /** Nevelkleuren achter en voor de lagen. */
  nevel?: { achter: string; voor: string };

dtsPropsFor.Podium:
/** Scrollvoortgang 0..1, bv. van useScroll() of useMotionValue(0.5). */
  progress: import('motion/react').MotionValue<number>;
  gepind: boolean;

dtsPropsFor.PolderFoto:
/** POLDER_SCHEMER of POLDER_DAGERAAD (exports van dit pakket). */
  scene: { map: string; horizon: number };
  /** Muispositie, bv. van useMuisParallax() uit dit pakket. */
  muisX: import('motion/react').MotionValue<number>;
  muisY: import('motion/react').MotionValue<number>;
  /** Horizontale positie van de foto op brede schermen (object-position x). */
  x?: string;
  mobielInStroom?: boolean;
  grond?: string;
  nevel?: string | null;
